    /// <summary>
    /// Allows access to the storage locations and data for the documents generated by the system.
    /// </summary>
    [ApiVersionNeutral]
    [Produces("application/json")]
    [Route("api/[controller]")]
    [ApiController]
    public class StorageController : ControllerBase
    {
        #region [-- ZipReadRetryPolicy --]

#pragma warning disable IDE1006 // Naming Styles
        private static readonly int ZipReadRetryCount = 2;
        private static readonly TimeSpan ZipReadSleepDuration = TimeSpan.FromSeconds(3);
        private static readonly string ZipReadExceptionMessage = "Cannot find central directory";

        /// <summary>
        /// The ZipReadRetryPolicy is a temporary measure to account for sometimes calls to StorageManager.GetDistributionPacketStream will
        /// fail with a central directory error but works fine on second try - once work is completed in DocSys.Storage to resolve the conflicts
        /// that cause this error, we can remove this retry policy
        /// </summary>
        private static readonly IAsyncPolicy ZipReadRetryPolicy = Policy
            .Handle<ZipException>(ex => ex.Message.StartsWith(ZipReadExceptionMessage))
            .WaitAndRetryAsync(
                ZipReadRetryCount,
                (r) => ZipReadSleepDuration,
                (e, t) => { });

#pragma warning restore IDE1006 // Naming Styles

        #endregion [-- ZipReadRetryPolicy --]

        private readonly IStorageManager _storageManager;
        private readonly ILogger _logger;
        private readonly IDocumentTransactionRepository _documentTransactionRepository;
        private readonly IEdi835Repository _edi835Repository;
        private readonly IPaymentRoutingApiClient _paymentRoutingApiClient;

        public StorageController(IStorageManager storageManager, IDocumentTransactionRepository documentTransactionRepository,
            IEdi835Repository edi835Repository, ILogger<StorageController> logger, IPaymentRoutingApiClient paymentRoutingApiClient)
        {
            _storageManager = storageManager;
            _documentTransactionRepository = documentTransactionRepository;
            _edi835Repository = edi835Repository;
            _logger = logger;
            _paymentRoutingApiClient = paymentRoutingApiClient;
        }

        /// <summary>
        /// Retrieves a single record from the database .
        /// </summary>
        /// <param name="archiveFileId">Identity key from the ArchiveFile table.</param>
        /// <returns>A single record of information about archive file.</returns>
        [HttpGet("Archive/{archiveFileId}")]
        [ProducesResponseType(typeof(IArchiveFile), 200)]
        [ProducesResponseType(404)]
        [Produces("application/json")]
        public async Task<IActionResult> GetArchiveForArchiveFileId(long archiveFileId)
        {
            try
            {
                var result = await _storageManager.GetArchiveForArchiveFileId(archiveFileId);
                return Ok(result);
            }
            catch (ArchiveFileNotFoundException e)
            {
                _logger.LogWarning(e, "Unable to locate db entry for ArchiveFileId [{ArchiveFileId}] on [{Hostname}].",
                    e.ArchiveFileId, e.Hostname);
                return NotFound();
            }
        }

        /// <summary>
        /// Retrieves all records about archive files with the supplied transactionId (in theory, should only be one,
        /// but may be more, depending on reissues, and/or other factors)
        /// </summary>
