        /// <returns>A collection of information about archive files.</returns>
        [HttpGet("Transaction/{transactionId}/Archive")]
        [ProducesResponseType(typeof(IEnumerable<IArchiveFile>), 200)]
        public async Task<IActionResult> GetArchivesForTransactionId(long transactionId)
        {
            var result = await _storageManager.GetArchivesForTransactionId(transactionId);

            return Ok(result);
        }

