        /// <summary>
        /// Download the zip archive file.
        /// </summary>
        /// <param name="archiveFileId">Identity of the ArchiveFile within the database.</param>
        /// <response code="200">Returns the requested file.</response>
        /// <response code="404">Unable to locate file.</response>
        [HttpGet("Archive/{archiveFileId}/Download")]
        [ProducesResponseType(typeof(FileContentResult), 200)]
        [ProducesResponseType(typeof(IArchiveFile), 404)]
        [Produces("application/zip", "application/json")]
        public async Task<IActionResult> DownloadArchiveFile(long archiveFileId)
        {
            // Get the Archive file for a given ID.
            try
            {
                var archiveFile =
                    (ArchiveFile)(await _storageManager.GetArchiveForArchiveFileId(archiveFileId));
                if (!System.IO.File.Exists(archiveFile.FullPath)) // Archive file exists in DB, but not no filesystem.
                {
                    _logger.LogWarning("Unable to locate file for ArchiveFileId [{ArchiveFileId}].", archiveFileId,
                        archiveFile.FullPath ?? "");
                    return NotFound(archiveFile);
                }

                byte[] allBytes = System.IO.File.ReadAllBytes(archiveFile.FullPath);
                return File(allBytes, "application/zip", archiveFile.FileName);
            }
            catch (ArchiveFileNotFoundException e)
            {
                _logger.LogWarning(e, "Unable to locate db entry for ArchiveFileId [{ArchiveFileId}] on [{Hostname}].",
                    e.ArchiveFileId, e.Hostname);
                return NotFound();
            }
            catch (ApplicationException e)
            {
                _logger.LogWarning(e, "Unable to locate db entry for ArchiveFileId [{ArchiveFileId}].",
                    archiveFileId);
                return NotFound();
            }
        }

        /// <summary>
        /// Download as single file from an archive, based on the archiveDetailId.
        /// </summary>
        /// <param name="archiveDetailId">Identity of the ArchiveDetail within the database.</param>
        /// <response code="200">Returns the requested file.</response>
        /// <response code="404">Unable to locate file.</response>
        [HttpGet("Archive/Detail/{archiveDetailId}/Download")]
        [ProducesResponseType(200)]
        [Produces("application/json", "application/octet-stream", "text/plain")]
        public async Task<IActionResult> DownloadArchiveDetail(long archiveDetailId)
        {
            DateTime zipDate = DateTime.Today;
            DateTime fixDate = new DateTime(2018, 12, 15);
            string message = string.Empty;
            try
            {
                using (var archiveDetailStream = await _storageManager.GetArchiveDetailStream(archiveDetailId))
                {
                    if (archiveDetailStream == null)
                    {
                        return NotFound();
                    }

                    // Ok, we have a zip archive, but the detail we're looking for may not be present.
                    // If the "file date" is prior to 12/15/2018, this is a known issue, and we are ok with just info. build breaks.
                    // after that date, and we need an error.
                    message = $"ArchiveFileId:[{archiveDetailStream.ArchiveFileId}] ArchiveDetailId:[{archiveDetailStream.ArchiveDetailId}] {archiveDetailStream.ZipFileName} => {archiveDetailStream.FileName}";
                    zipDate = archiveDetailStream.CreateDateTime;

                    // write archive detail to memory buffer so we can close/dispose the ArchiveDetailStream
                    var memoryStream = new MemoryStream();
                    using (var fileStream = archiveDetailStream.Open())
                    {
                        fileStream.CopyTo(memoryStream);
                        fileStream.Close();
                    }
                    memoryStream.Position = 0;

                    // return FileStreamResult from memory stream
                    return File(memoryStream, archiveDetailStream.ContentType, archiveDetailStream.FileName);
                }
            }
            catch (FileNotFoundException e)
            {
                if (zipDate < fixDate)
                {
                    _logger.LogInformation(e, $"File not found in zip archive. {message}");
                }
                else
                {
                    _logger.LogError(e, $"File not found in zip archive after {fixDate:MM/dd/yyy}, please investigate. {message}");
                }
            }
            // Anything other than FileNotFound will go to last chance exception handler, but in all cases, if we get here, the file
            // requested has not be delivered.
            return NotFound();
        }

        /// <summary>
        /// Download as single file from an archive, based on the TransactionId and the PayType.
        /// </summary>
        /// <param name="transactionId">Transaction Id (SETXID).</param>
        /// <param name="payType">5 letter Pay Type code, ignored for red card</param>
        /// <response code="200">Returns the requested file.</response>
        /// <response code="404">Unable to locate file.</response>
        [HttpGet("Archive/Detail/Download/{transactionId}/{payType}/DistributionPacket")]
        [ProducesResponseType(typeof(FileStreamResult), StatusCodes.Status200OK)]
        [ProducesResponseType(StatusCodes.Status404NotFound)]
        [Produces("application/json", "application/octet-stream", "text/plain")]
        public Task<IActionResult> GetDistributionPacket(long transactionId, string payType)
        {
            return ZipReadRetryPolicy.ExecuteAsync<IActionResult>(async () =>
            {
                using (var archiveDetailStream = await _storageManager.GetDistributionPacketStream(transactionId, payType, false))
                {
                    if (archiveDetailStream == null)
                    {
                        return NotFound();
                    }

                    // write archive detail to memory buffer so we can close/dispose the ArchiveDetailStream
                    // NOTE: we do NOT want to dispose of this MemoryStream object despite what CodeQL/Sonarqube says
                    // If we include a 'using' before the 'var memoryStream' then we see a "Cannot access disposed stream" exception
                    // Here is a stackoverflow discussion describing why we set the position to 0 and don't manually dispose of the stream
                    // https://stackoverflow.com/questions/36184509/why-am-i-getting-cannot-access-a-closed-stream-here
                    var memoryStream = new MemoryStream();
                    using (var fileStream = archiveDetailStream.Open())
                    {
                        await fileStream.CopyToAsync(memoryStream);
                        fileStream.Close();
                    }
                    memoryStream.Position = 0;

                    // return FileStreamResult from memory stream
                    return File(memoryStream, archiveDetailStream.ContentType, archiveDetailStream.FileName);
                }
            });
        }

