        /// <summary>
        /// Downloads the 835 file from the archive, based on the TransactionId.
        /// </summary>
        /// <param name="transactionId">Transaction Id (SETXID).</param>
        /// <param name="cancellationToken">A token that can be used to cancel the work.</param>
        /// <response code="200">Returns the requested file.</response>
        /// <response code="404">Unable to locate file.</response>
        /// <response code="409">Unable to locate file that should exist.</response>
        [HttpGet("Archive/Detail/Download/{transactionId}/Edi835")]
        [ProducesResponseType(typeof(FileStreamResult), StatusCodes.Status200OK)]
        [ProducesResponseType(StatusCodes.Status404NotFound)]
        [Produces("application/json", "text/plain")]
        public async Task<IActionResult> GetEdi835File(long transactionId, CancellationToken cancellationToken)
        {
            using var scope = _logger.BeginScope(new Dictionary<string, object> { ["TransactionId"] = transactionId });

            var getFile = await ZipReadRetryPolicy.ExecuteAsync<IActionResult>(async () =>
                {
                    using (var archiveDetailStream = await _storageManager.Get835File(transactionId))
                    {
                        if (archiveDetailStream == null)
                        {
                            return null;
                        }

                        // write archive detail to memory buffer so we can close/dispose the ArchiveDetailStream
                        var memoryStream = new MemoryStream();
                        using (var fileStream = archiveDetailStream.Open())
                        {
                            await fileStream.CopyToAsync(memoryStream).ConfigureAwait(false);
                        }
                        memoryStream.Position = 0;

                        // return FileStreamResult from memory stream
                        return File(memoryStream, archiveDetailStream.ContentType, archiveDetailStream.FileName);
                    }
                }).ConfigureAwait(false);

            if (getFile == null)
            {
                var edi835 = await _edi835Repository.GetMostRecent835(transactionId).ConfigureAwait(false);
                if (edi835 != null)
                {
                    return NotFoundProblemDetail(edi835.StatusCode.ToString());
                }
                else
                {
                    _logger.LogInformation("835 Lookup - Transaction Id is not expecting an 835 from an outside vendor");

                    var outbound835 = await _paymentRoutingApiClient.GetOutbound835Document(transactionId, cancellationToken);
                    if (outbound835 != null)
                    {
                        return File(outbound835.Stream, outbound835.ContentType, outbound835.FileName);
                    }

                    var edi = await _documentTransactionRepository.GetDocumentTransaction(transactionId).ConfigureAwait(false);
                    if (edi == null)
                    {
                        return NotFoundProblemDetail("TRANSACTION_NOT_FOUND");
                    }
                    else if (edi.IsEdi835Needed == false)
                    {
                        return NotFoundProblemDetail("835_NOT_NEEDED");
                    }
                }

                return NotFoundProblemDetail("835_PENDING");
            }

            return getFile;
        }

        /// <summary>
        /// Downloads the Outbound 835 file from the payment routing api, based on the TransactionId.
        /// </summary>
        /// <param name="transactionId">Transaction Id (SETXID).</param>
        /// <param name="cancellationToken">A token that can be used to cancel the work.</param>
        /// <response code="200">Returns the requested file.</response>
        /// <response code="404">Unable to locate file.</response>
        [HttpGet("Archive/Detail/Download/{transactionId}/OutboundEdi835")]
        [ProducesResponseType(typeof(FileStreamResult), StatusCodes.Status200OK)]
        [ProducesResponseType(StatusCodes.Status404NotFound)]
        [Produces("application/json", "text/plain")]
        public async Task<IActionResult> GetOutboundEdi835File(long transactionId, CancellationToken cancellationToken)
        {
            var getFile = await _paymentRoutingApiClient.GetOutbound835Document(transactionId, cancellationToken);
            if (getFile == null)
            {
                return NotFoundProblemDetail("TRANSACTION_NOT_FOUND");
            }

            return File(getFile.Stream, getFile.ContentType, getFile.FileName);
        }

        private IActionResult NotFoundProblemDetail(string detail)
        {
            var problemDetails = new ProblemDetails
            {
                Title = "Not Found",
                Type = "https://httpstatuses.com/404",
                Status = 404,
                Detail = detail
            };
            return NotFound(problemDetails);
        }

        private IActionResult ConflictProblemDetail(string detail)
        {
            var problemDetails = new ProblemDetails
            {
                Title = "Conflict",
                Type = "https://httpstatuses.com/409",
                Status = 409,
                Detail = detail
            };
            return NotFound(problemDetails);
        }
    }
